        'Only an IN_REVIEW Care Action can be resolved.'
      ) ||
      message.includes(
        'Care Action must have an assigned human owner before resolution.'
      ) ||
      message.includes(
        'Care Action review must be started before resolution.'
      ) ||
      message.includes(
        'AI or SYSTEM actor cannot resolve a Care Action.'
      ) ||
      message.includes(
        'Actor is not authorized to resolve this Care Action.'
      ) ||
      message.includes(
        'Only a RESOLVED Care Action can be reopened.'
      ) ||
      message.includes(
        'resolved timestamp before reopen'
      ) ||
      message.includes(
        'AI or SYSTEM actor cannot reopen'
      ) ||
      message.includes(
        'not authorized to reopen this Care Action'
      )
    ) {

