  TransferCareActionInput,
  StartCareActionReviewInput,
  ResolveCareActionInput,
  ReopenCareActionInput,
  CareActionDetails,
} from './care-action.types';

import {
  CareActionRepository,
} from './care-action.repository';

import {
  assertValidPriority,
  normalizeNullableDate,
  requireNonEmptyText,
} from './care-action.validation';

import {
  assertCareActionTransition,
} from './care-action.policy';
import { StartReviewAuthorizationService } from '../start-review-authorization/start-review-authorization.service';



import {
  ResolutionAuthorizationService,
} from '../resolution-authorization/resolution-authorization.service';

import {
  ReopenAuthorizationService,
} from '../reopen-authorization/reopen-authorization.service';

@Injectable()
export class CareActionService {

  constructor(
    private readonly db: DatabaseService,
    private readonly repository: CareActionRepository,
    private readonly startReviewAuthorization:
      StartReviewAuthorizationService,

    private readonly resolutionAuthorization:
      ResolutionAuthorizationService,

    private readonly reopenAuthorization:
      ReopenAuthorizationService,
) {}


  async get(
    residentId: string,
    patternId: string,
  ): Promise<CareAction | null> {

    const normalizedResidentId =
      requireNonEmptyText(
        residentId,
        'residentId',
      );

    const normalizedPatternId =
      requireNonEmptyText(
        patternId,
        'patternId',
      );

    return this.repository
      .findByResidentAndPattern(
        normalizedResidentId,
        normalizedPatternId,
      );

  }


  async getDetails(
    residentId: string,
    patternId: string,
  ): Promise<CareActionDetails | null> {

    const action =
      await this.get(
        residentId,
        patternId,
      );

    if (!action) {
      return null;
    }

    const [
      transferHistory,
      auditTrail,
    ] =
      await Promise.all([
        this.repository
          .listTransfers(
            action.id,
          ),

        this.repository
          .listAudit(
            action.id,
          ),
      ]);

    return {
      action,
      transferHistory,
      auditTrail,
    };

  }


  async getOrCreate(
    residentId: string,
    patternId: string,
  ): Promise<CareAction> {

    const normalizedResidentId =
      requireNonEmptyText(
        residentId,
        'residentId',
      );

    const normalizedPatternId =
      requireNonEmptyText(
        patternId,
        'patternId',
      );


    return this.db.withTransaction(
      async client => {

        const existing =
          await this.repository
            .findByResidentAndPattern(
              normalizedResidentId,
              normalizedPatternId,
              client,
            );

        if (existing) {
          return existing;
        }


        const created =
          await this.repository.insert(
            normalizedResidentId,
            normalizedPatternId,
            client,
          );


        await this.repository.insertAudit(
          {
            careActionId:
              created.id,

            residentId:
              created.residentId,

            patternId:
              created.patternId,

            eventType:
              'CREATED',

            actorId:
              null,

            actorRole:
              null,

            previousState:
              null,

            newState:
              {
                status:
                  created.status,
              },
          },
          client,
        );

                 updated.resolvedAt,

                resolutionReason:
                  updated.resolutionReason,

                careNote:
                  updated.careNote,

                assignedTo:
                  updated.assignedTo,

                assignedRole:
                  updated.assignedRole,
              },
          },
          client,
        );


        return updated;

      },
    );

  }


  async reopen(
    residentId: string,
    patternId: string,
    input: ReopenCareActionInput,
  ): Promise<CareAction> {

    const normalizedResidentId =
      requireNonEmptyText(
        residentId,
        'residentId',
      );

    const normalizedPatternId =
      requireNonEmptyText(
        patternId,
        'patternId',
      );

    const actorId =
      requireNonEmptyText(
        input.actorId,
        'actorId',
      );

    const actorRole =
      requireNonEmptyText(
        input.actorRole,
        'actorRole',
      );


    const reopenReason =
      requireNonEmptyText(
        input.reopenReason,
        'reopenReason',
      );


    return this.db.withTransaction(
      async client => {

        const action =
          await this.repository
            .findByResidentAndPatternForUpdate(
              normalizedResidentId,
              normalizedPatternId,
              client,
            );


        if (!action) {

          throw new Error(
            'Care Action not found.',
          );

        }

        this.reopenAuthorization.authorize({
          status:
            action.status,
          assignedTo:
            action.assignedTo,
          assignedRole:
            action.assignedRole,
          resolvedAt:
            action.resolvedAt,
          actorId,
          actorRole,
          reopenReason,
        });



        assertCareActionTransition(
          action.status,
          'IN_REVIEW',
        );


        const previousState = {
          status:
            action.status,

          startedAt:
            action.startedAt,

          resolvedAt:
            action.resolvedAt,

          resolutionReason:
            action.resolutionReason,

          careNote:
            action.careNote,

          assignedTo:
            action.assignedTo,

          assignedRole:
            action.assignedRole,
        };


        const updated =
          await this.repository.update(
            action.id,
            {
              status:
                'IN_REVIEW',

              startedAt:
                new Date(),

              resolvedAt:
                null,

              resolutionReason:
                null,

              careNote:
                null,
            },
            client,
          );


        await this.repository.insertAudit(
          {
            careActionId:
              updated.id,

            residentId:
              updated.residentId,

            patternId:
              updated.patternId,

            eventType:
              'REOPENED',

            actorId,
            actorRole,

            previousState,

            newState:
              {
                reopenReason,

                status:
                  updated.status,

                startedAt:
                  updated.startedAt,

                resolvedAt:
                  updated.resolvedAt,

                resolutionReason:
                  updated.resolutionReason,

                careNote:
                  updated.careNote,

                assignedTo:
                  updated.assignedTo,

                assignedRole:
                  updated.assignedRole,
              },
          },
          client,
        );


        return updated;

      },
    );

  }

}

